sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  // ----- Stepper -----
  c.steps = [
    { key: 'new',      label: 'New' },
    { key: 'details',  label: 'Hackathon Details' },
    { key: 'duration', label: 'Duration' },
    { key: 'rules',    label: 'Rules' }
  ];
  c.stepIndex = 0;

  // ----- Data Model -----
  c.model = { user: null };
  c.form = {
    email: '',
    hackathon_name: '',
    hackathon_details: '',
    start_dt: '',
    end_dt:   '',
    rules: ''
  };

  // sn-record-picker bound field
  c.userField = { name: 'user', value: '', displayValue: '' };

  // ----- UI/flow state -----
  c.state = {
    submitting: false,  // true while request in-flight (prevents double-click)
    locked:     false,  // true after successful create (hides controls)
    error: '',
    success: '',
    incident: null
  };
  c.dateError = false;

  // ----- Helpers -----
  c._fetchEmail = function(sysId) {
    if (!sysId) { c.form.email = ''; return; }
    c.state.submitting = true;
    c.server.get({ action: 'get_user_email', sys_id: sysId })
      .then(function(resp) {
        c.form.email = (resp.data && resp.data.email) || '';
      })
      .catch(function() {
        c.state.error = 'Failed to fetch email for selected user';
      })
      .finally(function() { c.state.submitting = false; });
  };

  // Listen to sn-record-picker change
  $scope.$on('field.change', function(evt, parms) {
    if (parms && parms.field && parms.field.name === 'user') {
      c.model.user = {
        value: parms.newValue,
        displayValue: parms.displayValue || parms.field.displayValue
      };
      c._fetchEmail(c.model.user.value);
      $scope.$applyAsync();
    }
  });

  c.prev = function() {
    if (c.state.locked || c.state.submitting) return;
    c.state.error = '';
    if (c.stepIndex > 0) c.stepIndex--;
  };

  // ----- Validation -----
  c._validateCurrent = function() {
    if (c.stepIndex === 0) {
      if (!c.model.user || !c.model.user.value) return 'Name is required';
      if (!c.form.email) return 'Email is required (auto-fill failed)';
    }
    if (c.stepIndex === 1) {
      if (!c.form.hackathon_name) return 'Hackathon name is required';
    }
    if (c.stepIndex === 2) {
      if (!c.form.start_dt || !c.form.end_dt) return 'Start and End date/time are required';
      try {
        var s = new Date(c.form.start_dt);
        var e = new Date(c.form.end_dt);
        c.dateError = e < s;
        if (c.dateError) return 'End must be after Start';
      } catch (e) {}
    }
    return '';
  };

  c.canNext   = function() { return !c._validateCurrent(); };
  c.canSubmit = function() { return !c._validateCurrent(); };

  c.next = function() {
    if (c.state.locked || c.state.submitting) return;
    var err = c._validateCurrent();
    c.state.error = err || '';
    if (!err && c.stepIndex < c.steps.length - 1) c.stepIndex++;
  };

  // Generate a per-submit idempotency key (client-side)
  function makeKey() {
    return Date.now() + '-' + Math.random().toString(36).slice(2);
  }

  // ----- Submit → create Incident on server (idempotent) -----
  c.submit = function() {
    if (c.state.locked || c.state.submitting) return;    // guard against double-clicks
    var err = c._validateCurrent();
    c.state.error = err || '';
    if (err) return;

    c.state.submitting = true;
    c.state.success = '';
    c.state.incident = null;

    var idemKey = makeKey();

    c.server.get({
      action: 'create_incident',
      payload: {
        idem_key:         idemKey,                         // idempotency token
        user_sys_id:      c.model.user && c.model.user.value,
        user_display:     c.model.user && c.model.user.displayValue,
        email:            c.form.email,
        hackathon_name:   c.form.hackathon_name,
        hackathon_details:c.form.hackathon_details,
        start_dt:         c.form.start_dt,
        end_dt:           c.form.end_dt,
        rules:            c.form.rules
      }
    }).then(function(resp) {
      if (resp.data && resp.data.error) {
        c.state.error = resp.data.error;
        return;
      }
      c.state.incident = resp.data && resp.data.incident ? resp.data.incident : null;
      if (c.state.incident) {
        c.state.success = 'Incident ' + c.state.incident.number + ' created';
        c.state.locked = true;                    // hide controls after success
      }
    }).catch(function() {
      c.state.error = 'Failed to create Incident';
    }).finally(function() {
      c.state.submitting = false;
    });
  };

  // Optional: start a fresh submission
  c.reset = function() {
    c.stepIndex = 0;
    c.model.user = null;
    c.userField = { name: 'user', value: '', displayValue: '' };
    c.form = { email:'', hackathon_name:'', hackathon_details:'', start_dt:'', end_dt:'', rules:'' };
    c.state = { submitting:false, locked:false, error:'', success:'', incident:null };
    c.dateError = false;
  };
};

sp_widget.css:
.hw-card { background: #fff; padding: 20px; border-radius: 8px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
.hw-title { margin-top: 0; margin-bottom: 16px; }

.hw-steps { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.hw-step { padding: 8px 12px; border-radius: 16px; background: #e9ecef; font-weight: 600; }
.hw-step.active { background: #13854e; color: #fff; }
.hw-step.done { background: #58a67a; color: #fff; }

.hw-panel { margin-top: 8px; }
.m-t-16 { margin-top: 16px; }
.m-t-8 { margin-top: 8px; }

.hw-footer { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

sp_widget.script:
(function() {
  data.error = '';
  if (!input) return;

  function toDisplay(v) {
    if (!v) return '';
    var s = ('' + v).replace('T', ' ');
    if (s.length === 16) s += ':00';
    return s;
  }

  function findByCorrelation(idemKey) {
    if (!idemKey) return null;
    var gr = new GlideRecord('incident');
    gr.addQuery('correlation_id', idemKey);
    gr.setLimit(1);
    gr.query();
    return gr.next() ? gr : null;
  }

  try {
    if (input.action === 'get_user_email') {
      var u = new GlideRecord('sys_user');
      if (u.get(String(input.sys_id))) {
        data.email = String(u.getValue('email')) || '';
      } else {
        data.email = '';
      }
      return;
    }

    if (input.action === 'create_incident') {
      var p = input.payload || {};

      // Server-side validation
      if (!p.user_sys_id) throw 'User (Name) is required';
      if (!p.email) throw 'Email is required';
      if (!p.hackathon_name) throw 'Hackathon name is required';
      if (!p.start_dt || !p.end_dt) throw 'Start and End date/time are required';

      var startGdt = new GlideDateTime(); startGdt.setDisplayValue(toDisplay(p.start_dt));
      var endGdt   = new GlideDateTime(); endGdt.setDisplayValue(toDisplay(p.end_dt));
      if (endGdt.getNumericValue() < startGdt.getNumericValue())
        throw 'End date/time must be after Start date/time';

      // ---- Idempotency: return existing if same idem_key already used ----
      var existing = findByCorrelation(p.idem_key);
      if (existing) {
        data.incident = { sys_id: ''+existing.getUniqueValue(), number: ''+existing.getValue('number') };
        return;
      }

      // Build description
      var desc = '';
      desc += 'Hackathon Submission\n';
      desc += '--------------------\n';
      desc += 'Name: ' + (p.user_display || '(selected user)') + '\n';
      desc += 'Email: ' + p.email + '\n\n';
      desc += 'Hackathon: ' + p.hackathon_name + '\n';
      if (p.hackathon_details) desc += 'Details:\n' + p.hackathon_details + '\n\n';
      desc += 'Duration:\n';
      desc += '  Start: ' + startGdt.getDisplayValue() + '\n';
      desc += '  End:   ' + endGdt.getDisplayValue() + '\n\n';
      if (p.rules) desc += 'Rules:\n' + p.rules + '\n';

      // Create Incident (write idem key into correlation_id)
      var inc = new GlideRecord('incident');
      inc.initialize();
      inc.setValue('short_description', 'Hackathon: ' + p.hackathon_name);
      inc.setValue('caller_id', p.user_sys_id);
      inc.setValue('contact_type', 'self-service');
      inc.setValue('description', desc);
      if (p.idem_key) inc.setValue('correlation_id', p.idem_key);

      var incSysId = inc.insert();

      data.incident = { sys_id: incSysId, number: '' + inc.getValue('number') };
      return;
    }

    data.error = 'Unsupported action';
  } catch (e) {
    // If a unique index on correlation_id blocks a duplicate insert,
    // we can safely fetch & return the existing record.
    var msg = String(e);
    if ((input && input.action === 'create_incident') && input.payload && input.payload.idem_key) {
      var fallback = findByCorrelation(input.payload.idem_key);
      if (fallback) {
        data.incident = { sys_id: ''+fallback.getUniqueValue(), number: ''+fallback.getValue('number') };
        return;
      }
    }
    data.error = msg;
  }
})();
